#include "storage/ProfileStore.hpp"
#include "storage/StorageEnvelope.hpp"
#include "platform/ProfileAccessMac.hpp"
#include <filesystem>
#include <iostream>
#include <atomic>
using namespace fathom;
int main(int argc,char**argv){try{if(argc!=2||std::filesystem::exists(argv[1]))throw std::runtime_error("Fresh root required");std::filesystem::create_directory(argv[1]);std::filesystem::permissions(argv[1],std::filesystem::perms::owner_all);storage::StoreOptions o;o.path=std::filesystem::path(argv[1])/"profile.sqlite";o.create=true;o.createdUtc="2026-10-25T00:00:00Z";std::atomic<bool> armed{false};o.diagnosticHook=[&](const std::string&phase,const std::string&){if(phase=="after_commit"&&armed.exchange(false))throw std::runtime_error("Controlled acknowledgment loss");};storage::ProfileStore s(o);int checks=0;auto ck=[&](bool b,const char*t){if(!b)throw std::runtime_error(t);++checks;std::cout<<"PASS "<<t<<'\n';};auto snap=[&]{auto r=s.snapshot(storage::newUuid()).get();ck(r.status==storage::Status::Confirmed,"snapshot confirmed");return r.data;};
const auto op=storage::newUuid(),owner=storage::newUuid();json::Value plan=json::Value::Object{{"original_start_operation",op},{"original_session_id",owner},{"synthetic_fixture",true}};auto first=s.createSessionWithIdentity(op,owner,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan).get();ck(first.status==storage::Status::Confirmed&&first.owner==owner,"nullable-budget original created");auto before=snap();auto replay=s.createSessionWithIdentity(op,owner,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan).get();ck(replay.status==storage::Status::Confirmed&&replay.owner==owner&&snap()==before,"nullable replay exact and readonly");ck(s.createSessionWithIdentity(op,owner,o.createdUtc,"Etc/UTC",600,plan).get().status==storage::Status::Conflict&&snap()==before,"NULL to positive conflicts without write");const auto other=storage::newUuid();auto otherPlan=plan;otherPlan.object()["original_session_id"]=other;ck(s.createSessionWithIdentity(op,other,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},otherPlan).get().status==storage::Status::Conflict&&snap()==before,"same operation cannot change owner");
ck(s.closeSession(storage::newUuid(),owner,"2026-10-25T00:00:01Z","cancelled").get().status==storage::Status::Confirmed,"original closes");before=snap();ck(s.createSessionWithIdentity(op,owner,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan).get().status==storage::Status::Conflict&&snap()==before,"closed original cannot reopen");
const auto op2=storage::newUuid(),owner2=storage::newUuid();auto plan2=json::Value::Object{{"original_start_operation",op2},{"original_session_id",owner2},{"synthetic_fixture",true}};armed=true;auto lost=s.createSessionWithIdentity(op2,owner2,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan2).get();ck(lost.status==storage::Status::Unresolved&&lost.owner==owner2,"lost acknowledgment retains reserved owner");before=snap();replay=s.createSessionWithIdentity(op2,owner2,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan2).get();ck(replay.status==storage::Status::Confirmed&&replay.owner==owner2&&snap()==before,"lost receipt adopts same original without write");
const auto op3=storage::newUuid(),owner3=storage::newUuid();auto plan3=json::Value::Object{{"original_start_operation",op3},{"original_session_id",owner3},{"synthetic_fixture",true}};ck(s.createSessionWithIdentity(op3,owner3,o.createdUtc,"Etc/UTC",600,plan3).get().status==storage::Status::Confirmed,"existing integer API creates positive budget");before=snap();ck(s.createSessionWithIdentity(op3,owner3,o.createdUtc,"Etc/UTC",600,plan3).get().status==storage::Status::Confirmed&&snap()==before,"existing integer API replay unchanged");ck(s.createSessionWithIdentity(op3,owner3,o.createdUtc,"Etc/UTC",std::optional<std::int64_t>{},plan3).get().status==storage::Status::Conflict&&snap()==before,"positive to NULL conflicts without write");std::cout<<"PASS checks="<<checks<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
